\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 13rectoa: \plain \f1\i\fs24 Circa distinctionem primam quaeritur: Utrum per studium sacrae theologiae sit scibile quod perfectio universi requirat\u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 
