\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs24 76verso (1. Prolog:) \plain \f1\i\fs24 Ars quam fingo mea lectoria dicitur ista\u8230 \'85\plain \f1\fs24  76verso (2. Prolog:) \plain \f1\i\fs24 Cum imperitorum ignorantia et errantium stultitia\u8230 \'85 \plain \f1\fs24 77recto (Text:)\plain \f1\i\fs24  Omnis dictio monosyllaba\u8230 \'85
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\fs20 
